CREATE INDEX "idx_book_genre_genre_id"        ON "book_genre" ("genre_id");
CREATE INDEX "idx_book_authors_author_id"     ON "book_author" ("author_id");
CREATE INDEX "idx_book_categories_cat_id"     ON "book_category" ("category_id");
CREATE INDEX "idx_book_copies_book_id"        ON "book_copy" ("book_id");
CREATE INDEX "idx_book_copies_status_id"      ON "book_copy" ("copy_status_id");
CREATE INDEX "idx_borrowings_member_id"       ON "borrowing" ("member_id");
CREATE INDEX "idx_borrowings_status_id"       ON "borrowing" ("status_id");
CREATE INDEX "idx_borrowing_items_copy_id"    ON "borrowing_item" ("book_copy_id");
CREATE INDEX "idx_reservations_member_id"     ON "reservation" ("member_id");
CREATE INDEX "idx_reservations_status_id"     ON "reservation" ("status_id");
CREATE INDEX "idx_reservation_items_book_id"  ON "reservation_item" ("book_id");
CREATE INDEX "idx_reservation_items_copy_id"  ON "reservation_item" ("book_copy_id");
